    # Colors section (extended palette)
    lines.append("### Colors")
    lines.append("| Role | Hex | CSS Variable |")
    lines.append("|------|-----|--------------|")
    for label, key, css_var in SEMANTIC_COLOR_ENTRIES:
        hex_val = colors.get(key, "")
